// A square spiral, walking outwards from the centre.
//
// Two details make it look like a spiral rather than a filled plane: each run length is
// used twice (leaving a gap between the arms), and the walk is kept a cell inside the
// border so it ends as a spiral instead of smearing along the edge.
val n = Level.sizeX
val path = BooleanArray(n * n)
var px = n / 2
var pz = n / 2
var dx = 1
var dz = 0
var step = 0
while (px in 1 until n - 1 && pz in 1 until n - 1) {
    repeat(1 + (step + 1) / 2) {
        if (px !in 1 until n - 1 || pz !in 1 until n - 1) return@repeat
        path[pz * n + px] = true
        px += dx
        pz += dz
    }
    val turn = dx
    dx = -dz
    dz = turn
    step++
}

return if (y == 0 && path[(z - Level.minZ) * Level.sizeX + (x - Level.minX)]) GREEN else null
